let all=[],skills=['siem','elastic','log analysis','alert triage','incident investigation','windows'];const demo=[['SOC Analyst Tier 1','DTS Solution','Dubai','100'],['L1 SOC Analyst','DeepSource Technologies','Dubai','84'],['Junior Cybersecurity Analyst','Gulf Secure Systems','Abu Dhabi','68'],['SIEM Analyst','Emirates Digital','UAE','84'],['Information Security Analyst','Falcon Group','Dubai','51']];async function load(){try{let r=await fetch('https://gulfsignal-api.onrender.com/api/jobs?location='+loc.value+'&skills='+skills.join(','));all=(await r.json()).jobs}catch(e){all=demo.filter(x=>loc.value==='UAE'||x[2]===loc.value).map((x,i)=>({id:i+1,title:x[0],company:x[1],location:x[2],source:'Demo company feed',url:'#',match:+x[3],matched:skills.slice(0,3),missing:['See role requirements'],status:'Saved'}))}count.textContent=all.length;render()}function render(){let f=document.querySelector('nav .active').dataset.s,list=f==='all'?all:all.filter(x=>x.status===f);jobs.innerHTML=list.map(j=>`<article class="card"><div class="top"><span class="tag">${j.status.toUpperCase()}</span><span class="score">${j.match}% match</span></div><h3>${j.title}</h3><div class="company">${j.company}</div><div class="meta">⌖ ${j.location} · ${j.source}</div><p class="why"><b>Why it fits:</b> ${j.matched.join(' · ')||'Role family aligned'}<br><span class="missing"><b>To strengthen:</b> ${j.missing.join(' · ')||'No gaps in demo profile'}</span></p><div class="actions"><a class="apply" href="${j.url}" target="_blank">Open company application ↗</a><select data-id="${j.id}"><option>Saved</option><option>Applied</option><option>Interview</option><option>Offer</option><option>Rejected</option></select></div></article>`).join('');document.querySelectorAll('.actions select').forEach(s=>{s.value=all.find(x=>x.id==s.dataset.id).status;s.onchange=async()=>{await fetch('/api/status',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job_id:+s.dataset.id,status:s.value})});load()}})}search.onclick=load;loc.onchange=load;document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');render()});cv.onchange=e=>{fileName.textContent=e.target.files[0]?.name||'Use demo profile or upload';load()};load();


